import type { Client, ClientContact } from "../../types/workforce"
import type { ClientFieldChange } from "../../types/work-crm"

/**
 * Client safety (CRM step 9): the field-by-field history of a client, the
 * deleted clients bin and merging two clients that are the same company.
 */

/** Fields followed in the History tab, in the order a change lists them. */
export const HISTORY_FIELDS = [
  "name", "legalName", "status", "email", "phone", "website", "address", "billingAddress", "ice", "taxId",
  "clientType", "country", "industry", "currency", "language", "hourlyRate", "paymentTermsDays", "creditLimit",
  "accountManagerId", "leadSource", "tags", "remindersOff", "convertedAt", "lostReason", "notes", "rateCard",
] as const satisfies readonly (keyof Client)[]
export type HistoryField = (typeof HISTORY_FIELDS)[number]

/** Days a deleted client stays in the bin before it is removed for good. */
export const BIN_DAYS = 30

/** A stored value as text: empty values are undefined so "" and missing don't count as a change. */
export function valueText(field: HistoryField, value: unknown): string | undefined {
  if (value === undefined || value === null || value === "") return undefined
  if (field === "tags") return (value as string[]).length ? (value as string[]).join(", ") : undefined
  if (field === "rateCard") {
    const lines = value as NonNullable<Client["rateCard"]>
    return lines.length ? lines.map((r) => `${r.employeeId ? `@${r.employeeId}` : r.jobTitle}: ${r.rate}`).join(", ") : undefined
  }
  return String(value)
}

const contactText = (c: ClientContact) => [c.name, c.position, c.email, c.phone].filter(Boolean).join(" · ")

/** What changed between two versions of a client, field by field; contacts and custom fields one by one. */
export function diffClient(before: Client, after: Client): ClientFieldChange[] {
  const changes: ClientFieldChange[] = []
  for (const field of HISTORY_FIELDS) {
    const a = valueText(field, before[field])
    const b = valueText(field, after[field])
    if (a !== b) changes.push({ field, before: a, after: b })
  }
  const old = new Map(before.contacts.map((c) => [c.id, c]))
  for (const c of after.contacts) {
    const was = old.get(c.id)
    old.delete(c.id)
    if (!was) changes.push({ field: "contact", after: contactText(c) })
    else if (contactText(was) !== contactText(c)) changes.push({ field: "contact", before: contactText(was), after: contactText(c) })
  }
  for (const c of old.values()) changes.push({ field: "contact", before: contactText(c) })
  const keys = new Set([...Object.keys(before.customFields ?? {}), ...Object.keys(after.customFields ?? {})])
  for (const key of keys) {
    const a = before.customFields?.[key] || undefined
    const b = after.customFields?.[key] || undefined
    if (a !== b) changes.push({ field: `custom:${key}`, before: a, after: b })
  }
  return changes
}

/** Whole days left before a deleted client is removed for good (0 when due). */
export function binDaysLeft(deletedAt: string, now: Date = new Date()): number {
  const passed = Math.floor((now.getTime() - Date.parse(deletedAt)) / 86_400_000)
  return Math.max(0, BIN_DAYS - passed)
}

/** Fields offered in the merge dialog when the two clients hold different values. */
export const MERGE_FIELDS = [
  "name", "legalName", "status", "email", "phone", "website", "address", "billingAddress", "ice", "taxId",
  "industry", "currency", "language", "hourlyRate", "paymentTermsDays", "creditLimit", "accountManagerId", "leadSource", "notes",
] as const satisfies readonly HistoryField[]
export type MergeField = (typeof MERGE_FIELDS)[number]
/** Which client's value to keep, per field; the kept client's value when not chosen. */
export type MergePicks = Partial<Record<MergeField, "keep" | "other">>

/** The fields where the two clients hold different, non-empty values: the ones to choose. */
export function mergeConflicts(keep: Client, other: Client): MergeField[] {
  return MERGE_FIELDS.filter((f) => {
    const a = valueText(f, keep[f])
    const b = valueText(f, other[f])
    return a !== undefined && b !== undefined && a !== b
  })
}

const sameContact = (a: ClientContact, b: ClientContact) =>
  (!!a.email && a.email.trim().toLowerCase() === b.email?.trim().toLowerCase()) || a.name.trim().toLowerCase() === b.name.trim().toLowerCase()

/**
 * The kept client after a merge: chosen values, blanks filled from the other
 * client, tags joined, the other client's contacts added unless already there,
 * custom fields filled. The kept client's main contact stays the main one.
 */
export function mergeClientValues(keep: Client, other: Client, picks: MergePicks = {}): Partial<Client> {
  const out: Partial<Client> = {}
  for (const f of MERGE_FIELDS) {
    const mine = valueText(f, keep[f])
    const theirs = valueText(f, other[f])
    if (theirs !== undefined && (picks[f] === "other" || mine === undefined)) Object.assign(out, { [f]: other[f] })
  }
  for (const f of ["clientType", "country", "convertedAt"] as const) if (!keep[f] && other[f]) Object.assign(out, { [f]: other[f] })
  const tags = [...new Set([...(keep.tags ?? []), ...(other.tags ?? [])])]
  if (tags.length) out.tags = tags.slice(0, 10)
  const added = other.contacts.filter((c) => !keep.contacts.some((k) => sameContact(k, c)))
  out.contacts = [...keep.contacts, ...added.map((c) => ({ ...c, isPrimary: keep.contacts.length === 0 && c.isPrimary }))]
  if (!keep.rateCard?.length && other.rateCard?.length) out.rateCard = other.rateCard
  if (other.customFields) out.customFields = { ...other.customFields, ...Object.fromEntries(Object.entries(keep.customFields ?? {}).filter(([, v]) => v)) }
  return out
}
